// client/src/components/admin/QuoteRequestsWidget.jsx
import { useEffect, useState } from "react";
const API_BASE = process.env.REACT_APP_API_BASE;

export default function QuoteRequestsWidget() {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [scheduleForm, setScheduleForm] = useState(null); // active quote being scheduled

  const fetchRequests = async () => {
    setLoading(true);
    const res = await fetch(`${API_BASE}api/quotes`, {
      headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
    });
    if (res.ok) {
      const data = await res.json();
      setRequests(data);
    }
    setLoading(false);
  };

  const updateStatus = async (id, status, extraData = {}) => {
    const res = await fetch(`${API_BASE}api/quotes/${id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.getItem("token")}`,
      },
      body: JSON.stringify({ status, ...extraData }),
    });
    if (res.ok) {
      setScheduleForm(null);
      fetchRequests();
    }
  };

  useEffect(() => {
    fetchRequests();
  }, []);

  if (loading) return <p>Loading quote requests…</p>;

  return (
    <section style={{ border: "1px solid #ddd", borderRadius: 8, padding: "1rem" }}>
      <h2>Quote Requests</h2>
      {requests.length === 0 && <p>No requests yet.</p>}

      <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
        {requests.map((r) => (
          <li key={r._id} style={{ marginBottom: "1rem", padding: "0.5rem", borderBottom: "1px solid #eee" }}>
            <strong>{r.companyName}</strong> — {r.contactName} ({r.email})
            <p>Services: {r.services.join(", ")}</p>
            <p>Status: <em>{r.status}</em></p>

            {r.status === "scheduled" && r.scheduledDate && (
              <p>📅 Scheduled: {new Date(r.scheduledDate).toLocaleString()}</p>
            )}

            <div style={{ display: "flex", gap: "0.5rem" }}>
              {["contacted", "scheduled", "closed"].map((st) => (
                <button
                  key={st}
                  onClick={() =>
                    st === "scheduled"
                      ? setScheduleForm(r)
                      : updateStatus(r._id, st)
                  }
                >
                  Mark {st}
                </button>
              ))}
            </div>
          </li>
        ))}
      </ul>

      {/* Scheduling Form */}
      {scheduleForm && (
        <div style={{ marginTop: "1rem", borderTop: "1px solid #ccc", paddingTop: "1rem" }}>
          <h3>Schedule Quote for {scheduleForm.contactName}</h3>
          <label>
            Date/Time:{" "}
            <input
              type="datetime-local"
              onChange={(e) => setScheduleForm({ ...scheduleForm, scheduledDate: e.target.value })}
            />
          </label>
          <label>
            Meeting Link:{" "}
            <input
              type="url"
              onChange={(e) => setScheduleForm({ ...scheduleForm, meetingLink: e.target.value })}
            />
          </label>
          <label>
            Notes:{" "}
            <textarea
              rows={3}
              onChange={(e) => setScheduleForm({ ...scheduleForm, adminNotes: e.target.value })}
            />
          </label>
          <div style={{ marginTop: "0.5rem" }}>
            <button
              onClick={() =>
                updateStatus(scheduleForm._id, "scheduled", {
                  scheduledDate: scheduleForm.scheduledDate,
                  meetingLink: scheduleForm.meetingLink,
                  adminNotes: scheduleForm.adminNotes,
                })
              }
            >
              Confirm Schedule
            </button>
            <button onClick={() => setScheduleForm(null)}>Cancel</button>
          </div>
        </div>
      )}
    </section>
  );
}
